import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build a dict of target_state for quick lookup
    state_dict = {}
    if len(target_state) > 0:
        for _, row in target_state.iterrows():
            oid = row["order_id"]
            state_dict[oid] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }

    # Remove duplicates by seq (keep first occurrence)
    if len(cdc_events) > 0:
        cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Apply replay guard: skip events where order exists in target_state and seq <= last_seq
    if len(cdc_events) > 0:
        filtered_events = []
        for _, event in cdc_events.iterrows():
            oid = event["order_id"]
            seq = event["seq"]
            if oid in state_dict:
                if seq <= state_dict[oid]["last_seq"]:
                    continue
            filtered_events.append(event)
        cdc_events = pd.DataFrame(filtered_events) if filtered_events else pd.DataFrame()

    # Sort remaining events by seq
    if len(cdc_events) > 0:
        cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Track which orders had a row at any point (for tombstone logic)
    orders_with_rows = set(state_dict.keys())

    # Apply events in order
    if len(cdc_events) > 0:
        for _, event in cdc_events.iterrows():
            oid = event["order_id"]
            op = event["op"]
            seq = event["seq"]

            if op == 'D':
                # Delete: remove the row if it exists
                if oid in state_dict:
                    del state_dict[oid]
            elif op in ['I', 'U']:
                if op == 'I':
                    # Insert: create new row from scratch
                    state_dict[oid] = {
                        "status": event["status"],
                        "amount": event["amount"],
                        "last_seq": seq
                    }
                    orders_with_rows.add(oid)
                else:  # op == 'U'
                    # Update: modify existing row or create if missing
                    if oid not in state_dict:
                        # U on missing order creates it
                        state_dict[oid] = {
                            "status": event["status"],
                            "amount": event["amount"],
                            "last_seq": seq
                        }
                        orders_with_rows.add(oid)
                    else:
                        # Update existing row
                        state_dict[oid]["status"] = event["status"]
                        # For U, NULL amount means keep existing amount
                        if pd.notna(event["amount"]):
                            state_dict[oid]["amount"] = event["amount"]
                        state_dict[oid]["last_seq"] = seq

    # Build new_state
    new_state_rows = []
    for oid, row_data in state_dict.items():
        new_state_rows.append({
            "order_id": oid,
            "status": row_data["status"],
            "amount": row_data["amount"],
            "last_seq": row_data["last_seq"]
        })

    new_state = pd.DataFrame(new_state_rows, columns=["order_id", "status", "amount", "last_seq"]) if new_state_rows else pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Build tombstones: orders that had a row (ever) and whose LAST applied event was a 'D'
    tombstone_rows = []

    if len(cdc_events) > 0:
        # For each order, find the last event in seq order
        last_event_per_order = {}
        for _, event in cdc_events.iterrows():
            oid = event["order_id"]
            seq = event["seq"]
            last_event_per_order[oid] = (seq, event["op"])

        for oid, (seq, op) in last_event_per_order.items():
            if oid in orders_with_rows and op == 'D':
                tombstone_rows.append({
                    "order_id": oid,
                    "deleted_seq": seq
                })

    tombstones = pd.DataFrame(tombstone_rows, columns=["order_id", "deleted_seq"]) if tombstone_rows else pd.DataFrame(columns=["order_id", "deleted_seq"])

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
